      compCat: 'Category', compRegion: 'Region', compSearch: 'Name, tax ID or manufacturer', compAllCats: 'All categories', compAllRegions: 'All regions', compDir: 'Direction', compFlowT: { all: 'All', ru_jp: 'Exporters to Japan', jp_ru: 'Importers from Japan', jp_office: 'Japanese companies in Russia' },
