      kChanged: (y) => `changed in ${y}`, kChangedTip: (y) => `The tax service record changed in ${y}: for offices and branches, in the accreditation register (address, activity, number of foreign staff or other details except the head of office); for subsidiaries, in EGRUL`,
      cKind: 'Type', cKindTip: 'Sort: subsidiaries, branches, then representative offices; the most recent first within each',
