      levelMiss: 'missing for A', recentTip: (n) => `. Documents in the 12 months before the data date: ${n}` + (n === 1 ? ' — thin evidence' : ''), lastRec: (y) => `. Register record from ${y}: the register does not show whether the channel works now`,
      compStale: (d, n) => `Company registers as of ${d} (${n} days ago): levels and “documents in the last 12 months” are counted up to that date; newer documents are not on the page.`,
